// Embeds the TradingView Lightweight Charts standalone build into a TS module so the
// chart WebView can run fully offline with a strict CSP (no CDN, no network access).
// Runs automatically on `npm install` (postinstall). Output is git-ignored.
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const src = join(root, 'node_modules/lightweight-charts/dist/lightweight-charts.standalone.production.js');
const outDir = join(root, 'charts/webview/generated');
const out = join(outDir, 'lwc-bundle.ts');

if (!existsSync(src)) {
  console.warn('[build-chart-bundle] lightweight-charts not installed yet; skipping.');
  process.exit(0);
}
const code = readFileSync(src, 'utf8');
const pkg = JSON.parse(readFileSync(join(root, 'node_modules/lightweight-charts/package.json'), 'utf8'));
// Prevent an inline </script> sequence from terminating the host <script> tag.
const safe = code.replace(/<\/script/gi, '<\\/script');
const sha256 = createHash('sha256').update(code).digest('hex');
mkdirSync(outDir, { recursive: true });
writeFileSync(
  out,
  `// AUTO-GENERATED by scripts/build-chart-bundle.mjs — do not edit.\n` +
    `// TradingView Lightweight Charts™ v${pkg.version} (Apache-2.0). Copyright (c) TradingView, Inc. https://www.tradingview.com/\n` +
    `export const LWC_VERSION = ${JSON.stringify(pkg.version)};\n` +
    `export const LWC_SHA256 = ${JSON.stringify(sha256)};\n` +
    `export const LWC_BUNDLE: string = ${JSON.stringify(safe)};\n`,
);
console.log(`[build-chart-bundle] wrote ${out} (lightweight-charts ${pkg.version}, sha256 ${sha256.slice(0, 12)}…)`);
